cd /Users/b612-lp/bench-workspaces/l5-20261030-wb-gateway/dabstep-payments-10 && python3 - <<'EOF'
import json,collections
f=json.load(open('inputs/fees.json'))
def generic(r):
    return (not r['account_type']) and r['capture_delay'] is None and r['monthly_fraud_level'] is None and r['monthly_volume'] is None and (not r['merchant_category_code'])
print('fully merchant-generic rules', sum(1 for r in f if generic(r)))
# distribution of which fields are restricted
for key in ['account_type','capture_delay','monthly_fraud_level','monthly_volume','merchant_category_code','is_credit','aci','intracountry']:
    n=sum(1 for r in f if (r[key] is None if not isinstance(r[key],list) else not r[key]))
    print(key,'restricted',1000-n)
# combos of scheme/credit/aci coverage
c=collections.Counter()
for r in f:
    for a in (r['aci'] or ['ANY']):
        for cr in ([r['is_credit']] if r['is_credit'] is not None else [True,False]):
            c[(r['card_scheme'],cr,a)]+=1
missing=[(s,cr,a) for s in ['TransactPlus','SwiftCharge','GlobalCard','NexPay'] for cr in (True,False) for a in 'ABCDEFG' if (s,cr,a) not in c]
print('missing combos', missing)
EOF

